import { jsonError } from "./errors";
import type { Env } from "../types";

type Method = "GET" | "POST" | "PATCH";

async function supabaseFetch(
  env: Env,
  token: string,
  path: string,
  method: Method,
  body?: unknown,
): Promise<Response> {
  const url = `${env.SUPABASE_URL.replace(/\/$/, "")}/rest/v1${path}`;

  const headers: Record<string, string> = {
    apikey: env.SUPABASE_PUBLISHABLE_KEY,
    authorization: `Bearer ${token}`,
    "content-type": "application/json",
  };

  if (method === "POST" || method === "PATCH") {
    headers.Prefer = "return=representation";
  }

  const response = await fetch(url, {
    method,
    headers,
    body: body ? JSON.stringify(body) : undefined,
  });

  return response;
}

export async function insertMyMember(env: Env, userToken: string, payload: unknown): Promise<Response> {
  return supabaseFetch(env, userToken, "/members", "POST", payload);
}

export async function getMyMemberById(env: Env, userToken: string, memberId: string): Promise<Response> {
  const path = `/members?member_id=eq.${encodeURIComponent(memberId)}&select=*`;
  return supabaseFetch(env, userToken, path, "GET");
}

export async function patchMyMemberById(
  env: Env,
  userToken: string,
  memberId: string,
  payload: unknown,
): Promise<Response> {
  const path = `/members?member_id=eq.${encodeURIComponent(memberId)}&select=*`;
  return supabaseFetch(env, userToken, path, "PATCH", payload);
}

export async function listMembersAsAdmin(env: Env): Promise<Response> {
  const url = `${env.SUPABASE_URL.replace(/\/$/, "")}/rest/v1/members?select=*`;
  return fetch(url, {
    method: "GET",
    headers: {
      apikey: env.SUPABASE_SERVICE_ROLE_KEY,
      authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE_KEY}`,
    },
  });
}

export type MembersListQuery = {
  grade?: number[];
  someAllergy?: boolean;
  sortBy?: "name" | "grade" | "updated_at";
  sortOrder?: "asc" | "desc";
};

function buildMembersListQuery(query: MembersListQuery): string {
  const params = new URLSearchParams();
  params.set("select", "*");

  if (query.grade && query.grade.length > 0) {
    const gradeValues = query.grade.map((value) => Number(value)).filter((value) => Number.isFinite(value));
    if (gradeValues.length > 0) {
      params.set("grade", `in.(${gradeValues.join(",")})`);
    }
  }

  if (typeof query.someAllergy === "boolean") {
    params.set("some_allergy", `eq.${query.someAllergy}`);
  }

  if (query.sortBy) {
    const order = query.sortOrder ?? "asc";
    params.set("order", `${query.sortBy}.${order}`);
  }

  return params.toString();
}

export async function listMembersAsAdminWithQuery(env: Env, query: MembersListQuery): Promise<Response> {
  const qs = buildMembersListQuery(query);
  const url = `${env.SUPABASE_URL.replace(/\/$/, "")}/rest/v1/members?${qs}`;
  return fetch(url, {
    method: "GET",
    headers: {
      apikey: env.SUPABASE_SERVICE_ROLE_KEY,
      authorization: `Bearer ${env.SUPABASE_SERVICE_ROLE_KEY}`,
    },
  });
}

