export async function parseSingleRow<T>(response: Response): Promise<T | Response> {
  if (!response.ok) return response;
  const rows = (await response.json()) as T[];
  if (!Array.isArray(rows) || rows.length === 0) return jsonError(404, "Not Found");
  return rows[0];
}

export async function parseRows<T>(response: Response): Promise<T[] | Response> {
  if (!response.ok) return response;
  const rows = (await response.json()) as T[];
  return rows;
}
