import { createRemoteJWKSet, jwtVerify, JWTPayload } from "jose";
import { jsonError } from "./errors";
import type { AuthContext, Env } from "../types";

let jwksCache: { url: string; jwks: ReturnType<typeof createRemoteJWKSet> } | null = null;

function getJwks(projectUrl: string) {
  const jwksUrl = `${projectUrl.replace(/\/$/, "")}/auth/v1/.well-known/jwks.json`;
  if (!jwksCache || jwksCache.url !== jwksUrl) {
    jwksCache = {
      url: jwksUrl,
      jwks: createRemoteJWKSet(new URL(jwksUrl)),
    };
  }
  return jwksCache.jwks;
}

function extractRoles(payload: JWTPayload): string[] {
  const appMetadata = payload.app_metadata as Record<string, unknown> | undefined;
  const roles = appMetadata?.roles;
  if (!Array.isArray(roles)) return [];
  return roles.filter((role): role is string => typeof role === "string");
}

function extractMemberId(payload: JWTPayload): string | undefined {
  const appMetadata = payload.app_metadata as Record<string, unknown> | undefined;
  const memberId = appMetadata?.member_id;
  return typeof memberId === "string" ? memberId : undefined;
}

export async function requireAuth(request: Request, env: Env): Promise<AuthContext | Response> {
  const authHeader = request.headers.get("authorization");
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return jsonError(401, "Unauthorized");
  }

  const token = authHeader.slice("Bearer ".length).trim();
  if (!token) return jsonError(401, "Unauthorized");

  try {
    const issuer = `${env.SUPABASE_PROJECT_URL.replace(/\/$/, "")}/auth/v1`;
    const audience = env.SUPABASE_JWT_AUDIENCE;
    const { payload } = await jwtVerify(token, getJwks(env.SUPABASE_PROJECT_URL), {
      issuer,
      ...(audience ? { audience } : {}),
    });

    if (typeof payload.sub !== "string") {
      return jsonError(401, "Unauthorized");
    }

    return {
      token,
      userId: payload.sub,
      memberId: extractMemberId(payload),
      roles: extractRoles(payload),
      claims: payload as Record<string, unknown>,
    };
  } catch {
    return jsonError(401, "Unauthorized");
  }
}

export function requireRole(auth: AuthContext, role: string): Response | null {
  if (!auth.roles.includes(role)) return jsonError(403, "Forbidden");
  return null;
}
